#!/usr/bin/env bash
# Nosana installation inspector. Generated by build_launcher.py; edit Python source.
# Run as the normal host user. Optional: --sudo --network --json --log /path/to/log
# Safe to stream to bash; no temp files, installs, wallet reads, or host repairs.
if ! command -v python3 >/dev/null 2>&1; then
    printf '%s\n' 'Python 3 is required (included in standard Ubuntu). No packages were installed.' >&2
    exit 3
fi
exec python3 - "$@" <<'NOSANA_INSPECT_PYTHON_4C87AC'
#!/usr/bin/env python3
"""Read-only Nosana installation inspection. Python 3.8+, standard library only.

Never starts/stops containers, reads wallets, fixes permissions, or registers a node.
Output is a bounded inventory, not a qualification or backend acceptance test.
"""
import argparse
import collections
import datetime
import grp
import ipaddress
import json
import os
from pathlib import Path
import pwd
import re
import selectors
import shutil
import signal
import stat
import subprocess
import sys
import time

VERSION = "0.2.0"
PUBLIC_DNS = {
    "8.8.8.8": "Google", "8.8.4.4": "Google",
    "2001:4860:4860::8888": "Google", "2001:4860:4860::8844": "Google",
    "1.1.1.1": "Cloudflare", "1.0.0.1": "Cloudflare",
    "2606:4700:4700::1111": "Cloudflare", "2606:4700:4700::1001": "Cloudflare",
}
INSPECT = ('{"image":{{json .Config.Image}},"user":{{json .Config.User}},'
           '"running":{{json .State.Running}},"mounts":{{json .Mounts}},'
           '"userns":{{json .HostConfig.UsernsMode}}}')
OUTER = ('{"privileged":{{json .HostConfig.Privileged}},'
         '"gpus":{{json .HostConfig.DeviceRequests}},"devices":{{json .HostConfig.Devices}}}')


def clean(value):
    """Defence in depth; command stderr, environment and logs are never published."""
    value = str(value)
    value = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", value)
    value = re.sub(r"[\x00-\x08\x0b-\x1f\x7f]", "", value)
    value = re.sub(r"(https?://)[^/\s@]+@", r"\1[redacted]@", value)
    value = re.sub(r"(https?://[^\s?#]+)[?#][^\s]*", r"\1?[redacted]", value)
    value = re.sub(r"(?i)(authorization\s*[:=]\s*)(?:bearer|basic)\s+\S+", r"\1[redacted]", value)
    value = re.sub(r"(?i)((?:token|password|secret|authorization|api[_-]?key)\s*[:=]\s*)\S+", r"\1[redacted]", value)
    value = re.sub(r'(?i)("(?:token|password|secret|authorization|api[_-]?key)"\s*:\s*)"(?:\\.|[^"\\])*"', r'\1"[redacted]"', value)
    value = re.sub(r"(?i)('(?:token|password|secret|authorization|api[_-]?key)'\s*:\s*)'(?:\\.|[^'\\])*'", r"\1'[redacted]'", value)
    return value[:4000]


def run(argv, timeout=12):
    """No shell, no input, finite timeout, deterministic English diagnostics."""
    env = dict(os.environ, LC_ALL="C", LANG="C")
    try:
        with subprocess.Popen(argv, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                              stderr=subprocess.DEVNULL, env=env, start_new_session=True) as p:
            data, deadline = bytearray(), time.monotonic() + timeout
            with selectors.DefaultSelector() as sel:
                sel.register(p.stdout, selectors.EVENT_READ)
                while sel.get_map():
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        os.killpg(p.pid, signal.SIGKILL)
                        p.wait()
                        return {"rc": 124, "out": "", "error": "timed out; result incomplete"}
                    for key, _ in sel.select(min(remaining, 0.2)):
                        block = os.read(key.fileobj.fileno(), 8192)
                        if not block:
                            sel.unregister(key.fileobj)
                        elif len(data) + len(block) > 131072:
                            os.killpg(p.pid, signal.SIGKILL)
                            p.wait()
                            return {"rc": 125, "out": "", "error": "output limit exceeded; result incomplete"}
                        else:
                            data.extend(block)
            try:
                p.wait(timeout=max(0.01, deadline-time.monotonic()))
            except subprocess.TimeoutExpired:
                os.killpg(p.pid, signal.SIGKILL)
                p.wait()
                return {"rc": 124, "out": "", "error": "timed out; result incomplete"}
            return {"rc": p.returncode, "out": data.decode("utf-8", "replace"),
                    "error": "" if p.returncode == 0 else "command failed (exit %d)" % p.returncode}
    except FileNotFoundError:
        return {"rc": 127, "out": "", "error": "command unavailable"}
    except subprocess.TimeoutExpired:
        return {"rc": 124, "out": "", "error": "timed out; result incomplete"}
    except OSError:
        return {"rc": 126, "out": "", "error": "command could not be executed"}


def mode_findings(mode, kind):
    """Mode-only policy; this does not claim access through ancestors or ACLs."""
    out = []
    if kind == "wallet":
        if mode & 0o044:
            out.append(("WARN", "wallet.read_mode", "Wallet mode grants group/other read bits; prefer owner-only access after confirming runtime identity. Parent traversal and ACLs affect actual exposure."))
        if mode & 0o022:
            out.append(("FAIL", "wallet.write_mode", "Wallet mode grants group/other write bits; a writable key can be replaced or damaged by an account that can reach it."))
        if mode & 0o111:
            out.append(("WARN", "wallet.execute_mode", "Wallet has unnecessary execute bits."))
        if not mode & 0o077:
            out.append(("PASS", "wallet.private_mode", "Wallet mode has no group/other permissions; ACL and runtime access checks are separate."))
    elif kind == "socket" and mode & 0o002:
        out.append(("FAIL", "socket.other_mode", "Runtime socket grants access to other users; do not use chmod 666 to resolve daemon access."))
    elif kind == "directory" and mode & 0o002:
        out.append(("WARN", "directory.other_write", "Directory grants other-user write access; inspect who can traverse and replace entries."))
    return out


def legacy_cli_findings(version):
    if version == "1.0.133":
        return [("WARN", "cli.legacy_onboarding", "Host @nosana/cli 1.0.133 uses /nodes/join-test-grid; current registration uses /nodes/register. Its bare onboarding error suppresses HTTP status/body. This does not identify the running node version or prove a blocked wallet.")]
    return []


def dns_addresses(text):
    addresses = []
    for token in text.split():
        try:
            addr = str(ipaddress.ip_address(token.split("#", 1)[0].split("%", 1)[0].strip("[],")))
            if addr not in addresses:
                addresses.append(addr)
        except ValueError:
            continue
    return addresses


def dns_policy(addresses):
    """Suggested-provider settings policy, separate from resolution success."""
    known = [a for a in addresses if a in PUBLIC_DNS]
    proxies = [a for a in addresses if a not in PUBLIC_DNS and (ipaddress.ip_address(a).is_loopback or ipaddress.ip_address(a).is_private or ipaddress.ip_address(a).is_link_local)]
    other = [a for a in addresses if a not in known and a not in proxies]
    if other:
        return "WARN", "DNS outside the suggested Google/Cloudflare set: %s. This is a settings difference, not proof DNS is broken." % ", ".join(other)
    if proxies:
        return "UNKNOWN", "Local/router/container DNS proxy: %s; its upstream provider cannot be inferred from this address.%s" % (", ".join(proxies), " Other configured servers match Google/Cloudflare." if known else "")
    if known:
        providers = ", ".join(sorted({PUBLIC_DNS[a] for a in known}))
        if len(known) < 2:
            return "WARN", "Suggested %s DNS found (%s), but only one server is listed; a secondary is recommended." % (providers, known[0])
        return "PASS", "Configured DNS matches suggested %s addresses: %s. Resolution is checked separately with --network." % (providers, ", ".join(known))
    return "UNKNOWN", "No upstream DNS addresses identified"


class Inspector:
    def __init__(self, args):
        self.args, self.rows, self.sudo = args, [], False
        self.user = pwd.getpwuid(os.getuid())
        self.home = Path(self.user.pw_dir)
        self.docker = ["docker", "--host", "unix:///var/run/docker.sock"]

    def add(self, status, ident, detail, evidence=None):
        row = {"status": status, "id": ident, "detail": clean(detail)}
        if evidence is not None:
            row["evidence"] = clean(evidence)
        self.rows.append(row)

    def command(self, ident, argv, required=False, timeout=12):
        r = run(argv, timeout)
        self.add("PASS" if r["rc"] == 0 else ("WARN" if required else "UNKNOWN"),
                 ident, "Query completed" if r["rc"] == 0 else r["error"], r["out"].strip() if r["rc"] == 0 else None)
        return r

    def json_command(self, argv):
        r = run(argv)
        try:
            return json.loads(r["out"]) if r["rc"] == 0 else None
        except (ValueError, TypeError):
            return None

    def container_dns(self, execution, label, nodejs=False):
        conf = run(execution + ["cat", "/etc/resolv.conf"])
        servers = [x for x in conf["out"].splitlines() if re.match(r"^\s*nameserver\s+", x)] if conf["rc"] == 0 else []
        self.add("INFO" if servers else "UNKNOWN", "network." + label + "_resolver",
                 "Existing container nameservers; this does not test a new workload network", "\n".join(servers) or conf["error"])
        status_, detail = dns_policy(dns_addresses("\n".join(servers)))
        self.add(status_, "network." + label + "_dns_policy", detail)
        if self.args.network:
            for host in ("api.nosana.com", "registry-1.docker.io"):
                # Orchestrator has Node; outer runtime normally has getent.
                args = ["node", "-e", 'require("dns").lookup(process.argv[1],e=>process.exit(e?1:0))', host] if nodejs else ["getent", "ahosts", host]
                r = run(execution + args, timeout=8)
                self.add("PASS" if r["rc"] == 0 else ("WARN" if r["rc"] in (1, 2) else "UNKNOWN"),
                         "network." + label + "_dns", host + ": " + ("resolved in existing container" if r["rc"] == 0 else r["error"]))

    def privileged(self, argv):
        return (["sudo", "-n", "--"] + argv) if self.sudo else argv

    def metadata(self, path):
        # stat follows symlinks, lstat/readlink below explain the redirect. No open().
        r = run(self.privileged(["/usr/bin/stat", "-L", "-c", "%a %u %g %F", "--", str(path)]))
        if r["rc"]:
            return None
        fields = r["out"].strip().split(" ", 3)
        try:
            return {"mode": int(fields[0], 8), "uid": int(fields[1]), "gid": int(fields[2]), "kind": fields[3]}
        except (ValueError, IndexError):
            return None

    def path_check(self, path, kind):
        path = Path(path)
        m = self.metadata(path)
        if m is None:
            self.add("UNKNOWN", kind + ".metadata", "Path missing, inaccessible, or query failed; no permission verdict", str(path))
            return None
        self.add("INFO", kind + ".metadata", "mode=%04o uid=%d gid=%d type=%s" % (m["mode"], m["uid"], m["gid"], m["kind"]), path)
        expected = {"wallet": "regular file", "socket": "socket", "directory": "directory"}.get(kind)
        if expected and m["kind"] != expected:
            self.add("FAIL", kind + ".type", "Expected " + expected, path)
        for status_, ident, detail in mode_findings(m["mode"], kind):
            self.add(status_, ident, detail, path)
        link = run(self.privileged(["/usr/bin/readlink", "--", str(path)]))
        if link["rc"] == 0:
            self.add("INFO", kind + ".symlink", "Symlink target is assessed by stat; do not chmod/chown the link blindly", link["out"].strip())
        acl = run(self.privileged(["/usr/bin/getfacl", "-cpn", "--", str(path)]))
        if acl["rc"]:
            self.add("UNKNOWN", kind + ".acl", "ACL inspection unavailable; mode bits alone cannot establish all effective permissions", path)
        elif re.search(r"^(?:default:|(?:user|group):\d+:)", acl["out"], re.M):
            self.add("WARN", kind + ".acl", "Extended/default ACL present; review its grants and mask before changing mode/owner", acl["out"].strip())
        else:
            self.add("PASS", kind + ".acl", "No named/default ACL entries", path)
        return m

    def wallet(self, state_dir, runtime=None):
        state_dir = Path(state_dir)
        key = state_dir / "nosana_key.json"
        # namei describes each ancestor, including symlink expansions, without reading data.
        self.command("wallet.ancestors", self.privileged(["/usr/bin/namei", "-l", "--", str(key)]))
        self.path_check(state_dir, "directory")
        m = self.path_check(key, "wallet")
        if m is None:
            self.add("INFO", "wallet.uncreated", "Before first startup a missing key can be normal. The inspector never generates one.")
            return
        read_ok = os.access(str(key), os.R_OK)
        write_ok = os.access(str(state_dir), os.W_OK | os.X_OK)
        self.add("PASS" if read_ok and write_ok else ("INFO" if runtime else "WARN"), "wallet.operator_access",
                 "Normal user key-readable=%s; state-directory writable/searchable=%s. This is required for a manual CLI under this user; container access is checked separately." % (read_ok, write_ok))
        if runtime:
            r = run(runtime + ["test", "-r", "/root/.nosana/nosana_key.json"])
            w = run(runtime + ["test", "-w", "/root/.nosana"])
            x = run(runtime + ["test", "-x", "/root/.nosana"])
            results = (r, w, x)
            known = all(t["rc"] in (0, 1) for t in results)
            self.add(("PASS" if all(t["rc"] == 0 for t in results) else "WARN") if known else "UNKNOWN", "wallet.runtime_access",
                     "Existing node container test -r/-w/-x: key-readable=%s; state-writable=%s; state-searchable=%s. No key contents opened; ownership need not match the login user." % tuple(str(t["rc"] == 0) if t["rc"] in (0, 1) else t["error"] for t in results))
        else:
            self.add("UNKNOWN", "wallet.runtime_access", "No supported running node context; service identity/access not established")
        self.storage(state_dir)

    def storage(self, path):
        try:
            v = os.statvfs(str(path))
            free = v.f_bavail * v.f_frsize
            inode_pct = 100 * v.f_favail / v.f_files if v.f_files else None
            low = free < 10 * 1024**3 or (inode_pct is not None and inode_pct < 5)
            self.add("WARN" if low else "PASS", "storage.capacity", "Free %.1f GiB; free inodes %s. Thresholds (10 GiB / 5%%) are inspection heuristics, not Nosana qualification requirements." % (free/1024**3, "unknown" if inode_pct is None else "%.1f%%" % inode_pct), path)
            self.add("FAIL" if v.f_flag & os.ST_RDONLY else "PASS", "storage.writable_mount", "Filesystem read-only=%s" % bool(v.f_flag & os.ST_RDONLY), path)
        except OSError:
            self.add("UNKNOWN", "storage.capacity", "Filesystem unavailable to the inspecting user", path)

    def system(self):
        release = {}
        try:
            for line in Path("/etc/os-release").read_text().splitlines():
                if "=" in line:
                    k, v = line.split("=", 1)
                    release[k] = v.strip('"')
        except OSError:
            pass
        self.add("INFO", "os.release", release.get("PRETTY_NAME", "unknown"))
        self.add("INFO" if release.get("ID") == "ubuntu" and release.get("VERSION_ID") in ("22.04", "24.04") else "WARN",
                 "os.baseline", "Reviewed installer baseline is Ubuntu 22.04/24.04. Other releases need separate compatibility evidence; the inspector does not infer a Podman/iptables bug from an OS name.")
        self.command("os.kernel", ["uname", "-r"])
        self.command("os.arch", ["uname", "-m"])
        virt = run(["systemd-detect-virt"])
        self.add("INFO" if virt["out"].strip() else "UNKNOWN", "os.virtualization", virt["out"].strip() or virt["error"])
        if "microsoft" in os.uname().release.lower():
            self.add("WARN", "os.wsl", "WSL detected; outside the supplied installer's native Ubuntu contract")
        self.command("os.secure_boot", ["mokutil", "--sb-state"])
        self.add("INFO", "os.secure_boot_policy", "Installer requests Secure Boot off. Enabled Secure Boot alone does not prove driver failure; loaded-driver and GPU results matter.")
        self.add("WARN" if Path("/var/run/reboot-required").exists() else "PASS", "os.reboot", "Reboot-required marker " + ("present" if Path("/var/run/reboot-required").exists() else "absent"))
        self.add("INFO", "user.identity", "uid=%d primary_gid=%d effective_groups=%s" % (os.getuid(), os.getgid(), ",".join(map(str, os.getgroups()))))
        try:
            dg = grp.getgrnam("docker")
            effective = dg.gr_gid in os.getgroups() or dg.gr_gid == os.getgid()
            configured = self.user.pw_name in dg.gr_mem or dg.gr_gid == self.user.pw_gid
            self.add("PASS" if effective else "WARN", "docker.group", "docker group configured=%s; active in this session=%s%s" % (configured, effective, "; new login may be needed" if configured and not effective else ""))
        except KeyError:
            self.add("INFO", "docker.group", "No docker group; daemon access is tested directly")
        sudo = run(["sudo", "-n", "true"])
        self.sudo = self.args.sudo and sudo["rc"] == 0
        self.add("INFO", "user.sudo", "Noninteractive sudo probe=%s; privileged metadata enabled=%s. Failure can mean a password is required, not absence of sudo rights." % ("available" if sudo["rc"] == 0 else "unavailable", self.sudo))
        self.path_check(self.home, "directory")
        if (self.home / ".docker").exists():
            self.path_check(self.home / ".docker", "directory")
        clock = run(["timedatectl", "show", "-p", "NTPSynchronized", "--value"])
        self.add("PASS" if clock["out"].strip() == "yes" else "UNKNOWN", "network.clock", "NTPSynchronized=" + (clock["out"].strip() or clock["error"]))
        resolver = run(["resolvectl", "dns"])
        if resolver["rc"] == 0:
            self.add("INFO", "network.resolver", "Effective systemd-resolved DNS", resolver["out"].strip())
            for line in resolver["out"].splitlines():
                addresses = dns_addresses(line)
                if addresses:
                    status_, detail = dns_policy(addresses)
                    self.add(status_, "network.dns_policy", line.split(":", 1)[0] + ": " + detail)
        else:
            # A disabled resolved service is valid when /etc/resolv.conf is managed
            # directly; publish nameservers only, not search domains/comments.
            try:
                lines = Path("/etc/resolv.conf").read_text().splitlines()
                servers = [x for x in lines if re.match(r"^\s*nameserver\s+", x)]
            except OSError:
                servers = []
            self.add("INFO" if servers else "UNKNOWN", "network.resolver", "resolved unavailable; resolv.conf nameservers (reachability not implied)", "\n".join(servers))
            addresses = dns_addresses("\n".join(servers))
            status_, detail = dns_policy(addresses)
            self.add(status_, "network.dns_policy", detail)
            if any(ipaddress.ip_address(a).is_loopback for a in addresses):
                try:
                    upstream = [x for x in Path("/run/systemd/resolve/resolv.conf").read_text().splitlines() if re.match(r"^\s*nameserver\s+", x)]
                except OSError:
                    upstream = []
                status_, detail = dns_policy(dns_addresses("\n".join(upstream)))
                self.add("INFO" if status_ == "PASS" else status_, "network.upstream_file_policy", "resolved API unavailable; generated-file snapshot only (may be stale). " + detail)
        self.command("network.default_route", ["ip", "-brief", "route", "show", "default"])
        self.command("network.iptables", ["iptables", "--version"])
        self.command("network.nft", ["nft", "--version"])
        self.command("network.firewall", self.privileged(["/usr/sbin/ufw", "status"]))
        self.add("INFO", "network.firewall_scope", "Versions/status do not prove network creation works. No firewall rules or networks are changed.")
        self.command("gpu.host", ["nvidia-smi", "--query-gpu=name,driver_version", "--format=csv,noheader"], required=True)
        self.command("gpu.kernel_module", ["cat", "/sys/module/nvidia/version"])
        self.command("gpu.disk_module", ["modinfo", "-F", "version", "nvidia"])
        self.command("gpu.toolkit", ["nvidia-ctk", "--version"])
        self.command("gpu.persistence", ["systemctl", "is-active", "nvidia-persistenced.service"])
        self.path_check("/run/nvidia-persistenced", "directory")
        self.path_check("/dev/fuse", "device")
        packages = run(["dpkg-query", "-W", "-f=${Package} ${Version} ${db:Status-Status}\n", "docker-ce", "docker.io", "containerd.io", "nvidia-container-toolkit", "iptables", "netavark", "podman"])
        self.add("INFO" if packages["out"].strip() else "UNKNOWN", "packages", "Installed package inventory; optional/alternative absent packages are not installation failures", packages["out"].strip() or packages["error"])
        self.storage(self.home)
        self.command("native.service", ["systemctl", "show", "nosana-host.service", "-p", "LoadState", "-p", "ActiveState", "-p", "User", "-p", "Group"])

    def cli(self):
        self.command("cli.nodejs", ["node", "--version"])
        cli = shutil.which("nosana")
        self.add("INFO", "cli.executable", cli or "No host-side nosana CLI; container installations do not require it")
        # Resolve installed package metadata locally; do not execute CLI or npm/npx.
        candidates = set()
        if cli:
            try:
                resolved = Path(cli).resolve()
                candidates.update(p / "package.json" for p in list(resolved.parents)[:4])
            except OSError:
                pass
        for root in ("/usr/lib/node_modules", "/usr/local/lib/node_modules", str(self.home / ".npm-global/lib/node_modules")):
            for name in ("@nosana/cli", "@nosana/node"):
                candidates.add(Path(root) / name / "package.json")
        found = set()
        for path in sorted(candidates):
            try:
                if path.stat().st_size > 262144:
                    continue
                data = json.loads(path.read_text())
                name, version = data.get("name"), data.get("version")
                if name not in ("@nosana/cli", "@nosana/node") or (name, version) in found:
                    continue
                found.add((name, version))
                self.add("INFO", "cli.package", "%s %s" % (name, version), path)
                if name == "@nosana/cli":
                    for row in legacy_cli_findings(version):
                        self.add(*row)
            except (OSError, ValueError, TypeError):
                continue
        if cli and not found:
            self.add("UNKNOWN", "cli.version", "CLI found but package version not identified; no CLI commands executed")

    def runtimes(self):
        if os.environ.get("DOCKER_HOST") or os.environ.get("DOCKER_CONTEXT"):
            self.add("WARN", "docker.context", "Docker environment override is set (value omitted). Inspector deliberately checks only local unix:///var/run/docker.sock; compare the operator's actual endpoint.")
        self.path_check("/var/run/docker.sock", "socket")
        base = self.docker
        ping = run(base + ["version", "--format", "{{.Client.Version}} {{.Server.Version}}"])
        if ping["rc"]:
            self.add("WARN", "docker.user_access", ping["error"] + "; normal user cannot query local daemon")
            if self.sudo:
                base = ["sudo", "-n", "--", "/usr/bin/docker", "--host", "unix:///var/run/docker.sock"]
                ping = run(base + ["version", "--format", "{{.Client.Version}} {{.Server.Version}}"])
        else:
            self.add("PASS", "docker.user_access", "Normal user can query local Docker without sudo")
        if ping["rc"]:
            self.add("UNKNOWN", "docker.daemon", "Local daemon unavailable to this inspection; " + ping["error"])
            self.wallet(self.home / ".nosana")
            return
        self.add("INFO", "docker.versions", "client/server: " + ping["out"].strip())
        self.command("docker.security", base + ["info", "--format", "{{json .SecurityOptions}}"])
        self.command("docker.runtimes", base + ["info", "--format", "{{range $k, $v := .Runtimes}}{{$k}} {{end}}"])
        self.command("docker.service", ["systemctl", "show", "docker.service", "-p", "ActiveState", "-p", "UnitFileState"])
        data_root = run(base + ["info", "--format", "{{.DockerRootDir}}"])
        if data_root["rc"] == 0 and data_root["out"].strip().startswith("/"):
            self.storage(Path(data_root["out"].strip()))
        outer = self.json_command(base + ["inspect", "--format", INSPECT, "podman"])
        if not outer:
            self.add("INFO", "runtime.topology", "No inspectable Docker container named podman; manual Docker/native/absent installation is possible")
            direct = self.json_command(base + ["inspect", "--format", INSPECT, "nosana-node"])
            if direct and direct.get("running"):
                self.add("INFO", "runtime.direct", "Direct Docker nosana-node found")
                self.node(base, direct)
            else:
                self.wallet(self.home / ".nosana")
            return
        self.add("INFO", "runtime.topology", "Podman-in-Docker container found; host-installed Podman is not required")
        self.add("INFO", "runtime.outer", json.dumps({k: outer.get(k) for k in ("image", "user", "running", "userns")}))
        mounts = {m.get("Destination", "").rstrip("/"): m for m in outer.get("mounts", [])}
        state = mounts.get("/root/.nosana")
        self.add("PASS" if state and state.get("RW") else "WARN", "runtime.state_mount", "Outer Nosana state bind mount must be writable", json.dumps(state) if state else "missing")
        for dst in ("/var/lib/containers", "/run/nvidia-persistenced"):
            m = mounts.get(dst)
            ok = bool(m and m.get("RW"))
            if dst == "/run/nvidia-persistenced":
                ok = ok and m.get("Propagation") == "rslave"
            self.add("PASS" if ok else "WARN", "runtime.mount", "Standard-launcher mount: " + dst, json.dumps(m))
        flags = self.json_command(base + ["inspect", "--format", OUTER, "podman"])
        if flags:
            for key, ok in (("privileged", flags.get("privileged")), ("gpus", flags.get("gpus")),
                            ("fuse", any(d.get("PathInContainer") == "/dev/fuse" for d in flags.get("devices") or []))):
                self.add("PASS" if ok else "WARN", "runtime." + key, "Standard launcher " + key + " setting present=" + str(bool(ok)))
        if not outer.get("running"):
            self.add("WARN", "runtime.outer_stopped", "Outer container stopped; no containers are started for inspection")
            self.wallet(Path(state["Source"]) if state else self.home / ".nosana")
            return
        pod = base + ["exec", "podman", "podman"]
        self.container_dns(base + ["exec", "podman"], "outer")
        self.command("runtime.podman", pod + ["--version"])
        self.command("runtime.network_backend", pod + ["info", "--format", "{{.Host.NetworkBackend}}"])
        self.command("runtime.inner_iptables", base + ["exec", "podman", "iptables", "--version"])
        self.command("gpu.outer", base + ["exec", "podman", "nvidia-smi", "--query-gpu=name,driver_version", "--format=csv,noheader"], required=True)
        self.command("gpu.cdi", base + ["exec", "podman", "nvidia-ctk", "cdi", "list"])
        node = self.json_command(pod + ["inspect", "--format", INSPECT, "nosana-node"])
        if node:
            self.node(pod, node, state)
        else:
            self.add("UNKNOWN", "runtime.node", "No inspectable inner nosana-node; may be absent or inaccessible")
            self.wallet(Path(state["Source"]) if state else self.home / ".nosana")
        networks = self.json_command(pod + ["network", "inspect", "NOSANA_GATEWAY"])
        if isinstance(networks, list) and networks:
            net = networks[0]
            selected = {k: net.get(k) for k in ("name", "driver", "subnets", "dns_enabled", "internal")}
            standard = net.get("driver") == "bridge" and any(s.get("subnet") == "192.168.101.0/24" and s.get("gateway") == "192.168.101.1" for s in net.get("subnets", []))
            self.add("PASS" if standard else "WARN", "runtime.gateway", "Gateway compared with standard launcher bridge/subnet; custom layouts require review", json.dumps(selected))
        else:
            self.add("UNKNOWN", "runtime.gateway", "Standard gateway absent or query failed; no network created")

    def node(self, runtime, node, outer_state=None):
        self.add("INFO", "runtime.node", json.dumps({k: node.get(k) for k in ("image", "user", "running", "userns")}))
        mounts = {m.get("Destination", "").rstrip("/"): m for m in node.get("mounts", [])}
        state = mounts.get("/root/.nosana")
        sock = mounts.get("/root/.nosana/podman/podman.sock")
        self.add("PASS" if state and state.get("RW") else "WARN", "runtime.node_state", "Node state mount must be writable", json.dumps(state))
        if outer_state:
            self.add("PASS" if sock and sock.get("Source") == "/podman.sock" else "WARN", "runtime.node_socket", "Standard nested-node provider socket mount", json.dumps(sock))
        # Only translate the known standard nesting. Custom mounts remain unknown.
        source = None
        if outer_state and state and state.get("Source", "").rstrip("/") == "/root/.nosana":
            source = outer_state.get("Source")
        elif not outer_state and state and state.get("Type") == "bind":
            source = state.get("Source")
        running = bool(node.get("running"))
        execution = runtime + ["exec", "nosana-node"] if running else None
        if execution:
            self.container_dns(execution, "node", nodejs=True)
            self.command("runtime.node_identity", execution + ["id"])
            # /nosana/package.json is the updater wrapper (0.0.0), NOT the node.
            # Resolve its installed launcher; never execute node start or npm.
            js = '''const fs=require("fs"),path=require("path");
const candidates=["/usr/local/lib/node_modules/@nosana/node/package.json"];
try{for(const v of fs.readdirSync("/root/.nosana-node").filter(v=>/^\\d+\\.\\d+\\.\\d+(?:[-+][A-Za-z0-9.-]+)?$/.test(v)).slice(0,32)){
 candidates.push(path.join("/root/.nosana-node",v,"lib/node_modules/@nosana/node/package.json"));
}}catch{}
for(const dir of (process.env.PATH||"").split(":")){try{
 let p=path.dirname(fs.realpathSync(path.join(dir,"nosana-node")));
 for(let i=0;i<5;i++){candidates.push(path.join(p,"package.json"));p=path.dirname(p)}
}catch{}}
const found=[];
for(const p of [...new Set(candidates)]){try{
 const data=JSON.parse(fs.readFileSync(p,"utf8"));
 if(data.name==="@nosana/node"&&!found.includes(data.version))found.push(data.version);
}catch{}}
if(found.length){console.log(JSON.stringify({name:"@nosana/node",installed_versions:found,node:process.version}));}else{process.exit(2);}'''
            self.command("runtime.node_package", execution + ["node", "-e", js])
            self.add("INFO", "runtime.version_scope", "Installed @nosana/node metadata is separate from host CLI and updater wrapper; a live update can temporarily differ from code already loaded by the process.")
            self.add("INFO", "gpu.node", "Node orchestrator need not contain nvidia-smi or receive GPUs; device visibility is checked on host and outer runtime. Workload CUDA remains untested.")
            if outer_state:
                self.command("runtime.socket_access", execution + ["sh", "-c", 'test -S /root/.nosana/podman/podman.sock && test -r /root/.nosana/podman/podman.sock && test -w /root/.nosana/podman/podman.sock'])
        else:
            self.add("WARN", "runtime.node_stopped", "Node is stopped; runtime access tests skipped")
        if source and source.startswith("/"):
            self.wallet(Path(source), execution)
        else:
            self.add("UNKNOWN", "wallet.mapping", "Cannot translate node state to host path; no ownership recommendation made")
        self.add("INFO", "gpu.limit", "nvidia-smi queries device visibility only. No CUDA workload, pull, benchmark, or qualification was run.")

    def network(self):
        if not self.args.network:
            self.add("SKIP", "network.external", "Use --network for optional DNS and TLS/HTTPS probes to public Nosana and Docker endpoints")
            return
        for host, url in (("api.nosana.com", "https://api.nosana.com/openapi.json"),
                          ("registry-1.docker.io", "https://registry-1.docker.io/v2/")):
            r = run(["getent", "ahosts", host], timeout=8)
            self.add("PASS" if r["rc"] == 0 and r["out"] else "WARN", "network.dns", host + ": " + ("resolved" if r["rc"] == 0 and r["out"] else r["error"]))
            r = run(["curl", "-q", "--proto", "=https", "--connect-timeout", "5", "--max-time", "10", "--silent", "--output", "/dev/null", "--write-out", "%{http_code}", url])
            code = r["out"].strip()
            ok = r["rc"] == 0 and code.isdigit() and 100 <= int(code) <= 599
            self.add("PASS" if ok else "WARN", "network.https", "%s TLS/HTTP transport: %s. HTTP errors (including registry 401) can still demonstrate transport; this is not successful onboarding." % (host, "HTTP " + code if ok else r["error"]))

    def logs(self):
        if not self.args.log:
            return
        patterns = {"legacy_onboarding_error": b"Error whilst submiting onboarding request",
                    "permission_denied": b"permission denied", "dns_failure": b"eai_again",
                    "iptables": b"iptables", "nftables": b"nftables",
                    "disk_full": b"no space left on device", "cuda_error": b"cuda error"}
        try:
            path = Path(self.args.log)
            if path.name in ("nosana_key.json", "id_rsa", "id_ed25519", ".env") or path.resolve().name in ("nosana_key.json", "id_rsa", "id_ed25519", ".env"):
                raise OSError("secret path refused")
            if not stat.S_ISREG(path.stat().st_mode):
                raise OSError("not regular")
            # Opt-in local file only. Output is counts; never raw log text.
            with path.open("rb") as f:
                f.seek(max(0, path.stat().st_size - 2 * 1024 * 1024))
                data = f.read(2 * 1024 * 1024).lower()
            counts = {k: data.count(v.lower()) for k, v in patterns.items()}
            self.add("INFO", "logs.signatures", "Counts in last <=2 MiB; no raw log text or contents published", json.dumps(counts))
            if counts["legacy_onboarding_error"]:
                self.add("WARN", "logs.onboarding", "Bare CLI 1.0.133 error means a non-OK HTTP response with status/body suppressed; Creating network is not proof of the failed step. Preserve exact version and UTC attempt timestamp for support.")
        except OSError:
            self.add("UNKNOWN", "logs.signatures", "Requested log is not a readable regular file")

    def collect(self):
        self.system()
        self.cli()
        self.runtimes()
        self.network()
        self.logs()
        self.add("INFO", "scope", "No repairs, wallet reads, package installs, container lifecycle changes, registration requests, signing, or transactions. Service/process metadata and existing-container exec queries only.")
        return self.rows


def checklist(report):
    """Translate collected evidence into a short checklist, without new probes."""
    rows, items, used = report["checks"], [], set()

    def select(ids):
        selected = [(i, r) for i, r in enumerate(rows) if r["id"] in ids]
        used.update(i for i, _ in selected)
        return [r for _, r in selected]

    def issue(row):
        ident, detail = row["id"], row["detail"]
        messages = {
            "os.baseline": "This Ubuntu release is outside the tested 22.04/24.04 setup.",
            "os.wsl": "WSL is outside the supported setup for this checker.",
            "os.reboot": "Ubuntu reports that a reboot is needed. Schedule it when the host can be stopped.",
            "gpu.host": "The NVIDIA GPU query failed; the GPU or driver needs investigation.",
            "gpu.toolkit": "The NVIDIA container toolkit could not be checked.",
            "gpu.persistence": "The NVIDIA persistence service is not confirmed running.",
            "gpu.outer": "The existing container runtime could not query the GPU.",
            "gpu.cdi": "GPU device configuration inside the container runtime could not be checked.",
            "docker.user_access": "Your normal user cannot query Docker without sudo.",
            "docker.group": "Your current login does not have Docker group access. A new login may be needed.",
            "docker.context": "A Docker override is set; this checker inspected only the local Docker socket.",
            "docker.daemon": "The local Docker daemon could not be reached.",
            "runtime.node_stopped": "The Nosana node container is stopped.",
            "runtime.outer_stopped": "The Podman container is stopped.",
            "runtime.state_mount": "The container's Nosana data folder is missing or not writable.",
            "runtime.node_state": "The node's data folder is missing or not writable.",
            "runtime.node_socket": "The node's connection to its container provider is missing or unexpected.",
            "runtime.socket_access": "The node cannot access its container-provider socket, or that check failed.",
            "runtime.gateway": "The expected Nosana container network is missing, different, or could not be checked.",
            "runtime.privileged": "The container is missing the privileged setting used by the standard launcher.",
            "runtime.gpus": "The standard container GPU request is missing.",
            "runtime.fuse": "The container is missing its expected /dev/fuse device.",
            "runtime.mount": "A required container mount is missing or has unexpected access settings.",
            "wallet.read_mode": "The wallet file allows group/other reads. Parent-folder permissions may still restrict who can reach it.",
            "wallet.write_mode": "The wallet file allows group/other writes. Accounts that can reach it could alter it.",
            "wallet.execute_mode": "The wallet file has unnecessary execute permissions.",
            "wallet.runtime_access": "The node's access to its wallet or data folder could not be confirmed.",
            "wallet.operator_access": "Your user cannot read the wallet or write its data folder for manual CLI use.",
            "wallet.mapping": "The wallet's location could not be determined for this installation.",
            "socket.other_mode": "The Docker socket allows other users to connect. Its permissions are too broad.",
            "directory.other_write": "A checked folder allows other users to write into it.",
            "network.clock": "The system clock is not confirmed synchronized.",
            "cli.legacy_onboarding": "Host CLI 1.0.133 uses an obsolete onboarding endpoint. It is separate from the running container's node version.",
            "logs.onboarding": "The supplied log contains the legacy onboarding error; it does not prove the wallet is blocked.",
        }
        if ident in ("network.dns", "network.outer_dns", "network.node_dns", "network.https"):
            host = detail.split(" ", 1)[0].rstrip(":")
            action = "HTTPS connection" if ident == "network.https" else "DNS lookup"
            location = " inside a container" if ident in ("network.outer_dns", "network.node_dns") else ""
            return "%s to %s%s %s." % (action, host, location, "timed out" if "timed out" in detail or "exit 28" in detail else "failed or could not be checked")
        if ident.endswith(".acl"):
            return "Extra file-access rules need review." if row["status"] == "WARN" else "Could not inspect extra file-access rules (ACLs)."
        if ident.endswith(".metadata") or ident == "wallet.ancestors":
            return "A required file or folder is missing, inaccessible, or could not be checked. Use --details for its path."
        if ident == "storage.capacity":
            return "Free disk space or free file entries are low." if row["status"] == "WARN" else "Could not check free space on a required filesystem."
        if ident == "storage.writable_mount":
            return "A required filesystem is read-only."
        if ident.endswith("dns_policy"):
            if row["status"] == "UNKNOWN":
                return "Could not confirm the upstream DNS provider behind a local DNS proxy."
            return detail.split(". This is", 1)[0].split(". Resolution", 1)[0].rstrip(".") + "."
        return messages.get(ident, clean(detail))

    def add(label, ok, explanations=()):
        explanations = list(dict.fromkeys(explanations))
        items.append({"ok": bool(ok), "label": label, "explanation": " ".join(explanations) if not ok else ""})

    def group(label, required, extra=(), allow_info=False):
        selected = select(set(required) | set(extra))
        missing = set(required) - {r["id"] for r in selected}
        bad = [r for r in selected if r["status"] in ("WARN", "FAIL", "UNKNOWN")]
        ok = not missing and not bad and all(r["status"] == "PASS" or allow_info and r["status"] == "INFO" for r in selected)
        explanations = [issue(r) for r in bad]
        if missing or not explanations and not ok:
            explanations.append("This check could not be completed for the detected installation.")
        add(label, ok, explanations)

    def endpoints(label, required):
        selected = select(set(required))
        bad = [r for r in selected if r["status"] != "PASS"]
        missing = []
        for ident in required:
            seen = {r["detail"].split(" ", 1)[0].rstrip(":") for r in selected if r["id"] == ident}
            missing += [host for host in ("api.nosana.com", "registry-1.docker.io") if host not in seen]
        explanation = [issue(r) for r in bad]
        if missing:
            explanation.append("Not all required connections were checked; results are incomplete.")
        add(label, not bad and not missing, explanation)

    group("Ubuntu installation", ("os.baseline",), ("os.wsl",), allow_info=True)
    group("NVIDIA GPU detected", ("gpu.host",))
    group("NVIDIA container toolkit", ("gpu.toolkit", "gpu.persistence"))
    group("GPU visible inside the container runtime", ("gpu.outer", "gpu.cdi"))
    group("Docker access", ("docker.user_access",), ("docker.group", "docker.context", "docker.daemon"), allow_info=True)

    outer = select({"runtime.outer"})
    node = select({"runtime.node"})
    stopped = select({"runtime.outer_stopped", "runtime.node_stopped"})
    nested = bool(outer)
    try:
        running = bool(node) and all(json.loads(r.get("detail", "{}"))["running"] is True for r in node + outer)
    except (ValueError, KeyError, TypeError):
        running = False
    add("Nosana containers running", running and not stopped,
        [issue(r) for r in stopped] or ["Could not confirm a running Nosana container. No containers were started."])

    config = ["runtime.node_state"]
    if nested:
        config += ["runtime.state_mount", "runtime.mount", "runtime.privileged", "runtime.gpus", "runtime.fuse", "runtime.node_socket", "runtime.socket_access", "runtime.gateway", "runtime.podman", "runtime.network_backend"]
    group("Nosana container setup", config)
    group("Free disk space and writable storage", ("storage.capacity", "storage.writable_mount"))
    group("System clock synchronized", ("network.clock",))
    group("No reboot pending", ("os.reboot",))

    dns = select({"network.dns_policy", "network.outer_dns_policy"})
    node_policy = select({"network.node_dns_policy"})
    gateway = [r for r in rows if r["id"] == "runtime.gateway" and r["status"] == "PASS"]
    node_servers = [r.get("evidence", "") for r in rows if r["id"] == "network.node_resolver"]
    # A node using the verified standard bridge DNS is expected, not a fault.
    expected_proxy = bool(gateway and node_servers) and all(dns_addresses(s) == ["192.168.101.1"] for s in node_servers)
    dns += [r for r in node_policy if not (expected_proxy and r["status"] == "UNKNOWN")]
    bad_dns = [r for r in dns if r["status"] != "PASS"]
    explanation = [issue(r) for r in bad_dns]
    if any(r["id"] == "network.dns_policy" and r["status"] == "UNKNOWN" for r in dns):
        explanation = ["Could not confirm the host's live DNS servers."] + [issue(r) for r in bad_dns if r["id"] != "network.dns_policy"]
        if any(r["id"] == "network.upstream_file_policy" and "matches suggested Google" in r["detail"] for r in rows):
            explanation.append("Its saved DNS settings list Google, but the live settings query did not answer.")
    have_host = any(r["id"] == "network.dns_policy" for r in dns)
    have_outer = not nested or any(r["id"] == "network.outer_dns_policy" for r in dns)
    if not have_host or not have_outer:
        explanation.append("DNS settings could not be fully checked.")
    add("Google/Cloudflare DNS settings", have_host and have_outer and not bad_dns, explanation)

    if not any(r["id"] == "network.external" and r["status"] == "SKIP" for r in rows):
        dns_ids = ["network.dns"] + (["network.outer_dns", "network.node_dns"] if nested else [])
        endpoints("DNS lookups", dns_ids)
        endpoints("HTTPS connections to Nosana and Docker", ("network.https",))
    group("Nosana can access its wallet", ("wallet.runtime_access",), ("wallet.mapping", "wallet.operator_access"), allow_info=True)
    group("Wallet file permissions", ("wallet.metadata", "wallet.acl", "wallet.ancestors"),
          ("wallet.read_mode", "wallet.write_mode", "wallet.execute_mode", "wallet.type"), allow_info=True)
    permission_ids = {r["id"] for r in rows if r["id"].startswith(("directory.", "socket.", "device.")) and r["id"] not in ("directory.symlink", "socket.symlink")}
    group("Folder and Docker socket permissions", ("socket.metadata", "socket.acl"), permission_ids, allow_info=True)

    # Keep any other explicit problems visible without dumping optional inventory.
    for i, row in enumerate(rows):
        if i not in used and row["status"] in ("WARN", "FAIL"):
            label = "Legacy CLI onboarding" if row["id"] == "cli.legacy_onboarding" else "Additional finding"
            add(label, False, [issue(row)])
    return items


def render_checklist(report):
    items = checklist(report)
    lines = ["Nosana installation check — %s" % clean(report.get("host", "host")), ""]
    for item in items:
        lines.append(("✅ " if item["ok"] else "❌ ") + item["label"])
        if not item["ok"]:
            lines.append("   " + item["explanation"])
    count = sum(not item["ok"] for item in items)
    lines += ["", "%d passed · %d need attention" % (len(items)-count, count),
              "Read-only — no settings changed. Details: --details or --json."]
    if any(r["id"] == "network.external" and r["status"] == "SKIP" for r in report["checks"]):
        lines.append("Internet tests were not run. Add --network to include them.")
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--sudo", action="store_true", help="allow noninteractive sudo for selected metadata queries; does not prompt")
    parser.add_argument("--network", action="store_true", help="perform bounded public DNS/HTTPS transport probes (no registration)")
    parser.add_argument("--json", action="store_true", help="emit JSON instead of text")
    parser.add_argument("--details", action="store_true", help="show the full technical report instead of the short checklist")
    parser.add_argument("--log", metavar="PATH", help="opt-in local log signature counts only, last 2 MiB; never prints raw logs")
    args = parser.parse_args()
    if os.geteuid() == 0:
        parser.error("Run as the normal host user, not sudo python3; use --sudo for optional privileged metadata")
    start = time.monotonic()
    if not args.json and not args.details:
        print("Checking installation…", flush=True)
    inspector = Inspector(args)
    rows = inspector.collect()
    counts = dict(collections.Counter(r["status"] for r in rows))
    report = {"inspector_version": VERSION, "utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
              "host": clean(os.uname().nodename), "duration_seconds": round(time.monotonic()-start, 2),
              "counts": counts, "checks": rows}
    if args.json:
        print(json.dumps(report, indent=2))
    elif args.details:
        print("Nosana installation inspection %s | %s | %s" % (VERSION, report["host"], report["utc"]))
        for row in rows:
            print("[%s] %s: %s" % (row["status"], row["id"], row["detail"]))
            if row.get("evidence"):
                print("  " + row["evidence"].replace("\n", "\n  "))
        print("Summary: %s | %.2fs" % (json.dumps(counts, sort_keys=True), report["duration_seconds"]))
        print("PASS refers to the named check only. WARN/UNKNOWN need context; this is not a qualification result.")
    else:
        print(render_checklist(report))
    return 2 if counts.get("FAIL") else 1 if counts.get("WARN") or any(not item["ok"] for item in checklist(report)) else 0


if __name__ == "__main__":
    sys.exit(main())

